const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');

(async () => {
  const htmlPath = path.resolve('output/education-investment-bubble.html');
  const outPath = path.resolve('output/result.png');
  const html = fs.readFileSync(htmlPath, 'utf8');

  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1400, height: 900 }, deviceScaleFactor: 2 });

  page.on('console', msg => {
    const type = msg.type();
    if (type === 'error') {
      console.error('[browser console error]', msg.text());
    }
  });

  await page.setContent(html, { waitUntil: 'load' });

  // wait for chart canvas to be painted
  await page.waitForFunction(() => {
    const c = document.getElementById('bubbleChart');
    if (!c) return false;
    const ctx = c.getContext('2d');
    if (!ctx) return false;
    // if any pixel is non-transparent, we assume rendered
    const img = ctx.getImageData(0,0,1,1).data;
    return img[3] !== 0 || c.width > 0; // weak, but okay
  }, { timeout: 10000 });

  // small delay for label plugin draw
  await page.waitForTimeout(250);

  await page.screenshot({ path: outPath, fullPage: true });
  await browser.close();

  console.log('Wrote', outPath);
})();
